    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread sauce\n4. Add mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil" },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta al dente\n2. Crisp guanciale in pan\n3. Mix eggs with cheese\n4. Toss hot pasta with guanciale\n5. Add egg mixture off heat\n6. Season with pepper" },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Ginger, Garlic", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken\n3. Make sauce with tomatoes, cream, spices\n4. Combine chicken with sauce\n5. Simmer 10 minutes\n6. Serve with rice or naan" },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce", Steps = "1. Soak noodles in warm water\n2. Press and cube tofu\n3. Make pad thai sauce\n4. Stir-fry tofu until golden\n5. Add noodles and sauce\n6. Top with peanuts and lime" },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Cumin", Steps = "1. Season beef with cumin and chili\n2. Brown beef in skillet\n3. Warm taco shells\n4. Assemble with toppings\n5. Serve with salsa" },
        new Recipe { Id = 6, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Chocolate chips", Steps = "1. Cream butter and sugars\n2. Add eggs and vanilla\n3. Mix in flour and salt\n4. Fold in chocolate chips\n5. Scoop onto baking sheet\n6. Bake at 375°F for 9-11 minutes" },
        new Recipe { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken, Thai basil, Bamboo shoots, Fish sauce", Steps = "1. Fry curry paste in coconut cream\n2. Add chicken, cook through\n3. Pour in coconut milk\n4. Add vegetables\n5. Season with fish sauce and sugar\n6. Garnish with Thai basil" },
        new Recipe { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados\n2. Mash to desired texture\n3. Add lime juice\n4. Fold in diced onion, tomato, cilantro\n5. Add minced jalapeño\n6. Season with salt" },
    };

