@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

@if (string.IsNullOrEmpty(Category))
{
    <h1>Browse Recipes</h1>
    <p>Select a category to explore recipes.</p>
    <div class="list-group">
        @foreach (var cat in Categories)
        {
            <a href="recipes/@cat.ToLower()" class="list-group-item list-group-item-action">@cat</a>
        }
    </div>
}
else
{
    <h1>@Category Recipes</h1>
    <a href="recipes" class="btn btn-outline-secondary btn-sm mb-3">&larr; All Categories</a>

    @if (Recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>@recipe.AverageRating.ToString("0.0") ★ (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? Category { get; set; }
