              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            ★
        </span>
    }

    @if (Submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating;
    private bool Submitted;

