@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the collection.
        <a href="recipes" class="alert-link">Browse recipes</a> to see it.
    </div>
}

<EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => Submission.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Thai">Thai</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="American">American</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => Submission.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="Submission.Ingredients"
                       placeholder="List ingredients separated by commas" />
        <ValidationMessage For="() => Submission.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps"
                       placeholder="Describe each step on a new line" />
        <ValidationMessage For="() => Submission.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission Submission { get; set; } = new();
    private bool SubmitSuccess;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) ||
            string.IsNullOrWhiteSpace(Submission.Category) ||
            string.IsNullOrWhiteSpace(Submission.Ingredients) ||
            string.IsNullOrWhiteSpace(Submission.Steps))
        {
            return;
        }

        RecipeService.AddRecipe(Submission);
        SubmitSuccess = true;
        Submission = new RecipeSubmission();
    }
}

