private IReadOnlyList<string> Categories = [];
private IReadOnlyList<RecipeHub.Models.Recipe> Recipes = [];

protected override void OnParametersSet()
{
    Categories = RecipeService.GetCategories();
    if (!string.IsNullOrEmpty(Category))
    {
        Recipes = RecipeService.GetRecipesByCategory(Category);
        // Title-case the category for display
        Category = Categories.FirstOrDefault(c => c.Equals(Category, StringComparison.OrdinalIgnoreCase)) ?? Category;
    }
}

